using StardewModdingAPI;\nusing System.Collections.Generic;\nusing System.IO;\n\nnamespace EnhancedSchoolsMod\n{\n    public class DataManager\n    {\n        private readonly IModHelper Helper;\n        private readonly IMonitor Monitor;\n        private readonly string DataPath;\n        public Dictionary<string, ChildSchoolData> ChildrenSchoolData { get; private set; } = new();\n\n        public DataManager(IModHelper helper, IMonitor monitor)\n        {\n            Helper = helper;\n            Monitor = monitor;\n            DataPath = Path.Combine(helper.DirectoryPath, \"school_data\");\n            if (!Directory.Exists(DataPath)) Directory.CreateDirectory(DataPath);\n        }\n\n        public void LoadChildSchoolData() => Monitor.Log(\"Loading child school data...\", LogLevel.Info);\n        public void SaveChildSchoolData() => Monitor.Log(\"Saving child school data...\", LogLevel.Info);\n\n        public ChildSchoolData? GetChildData(string childName)\n        {\n            ChildrenSchoolData.TryGetValue(childName, out var data);\n            return data;\n        }\n\n        public void UpdateChildData(string childName, ChildSchoolData data)\n        {\n            ChildrenSchoolData[childName] = data;\n            SaveChildSchoolData();\n        }\n    }\n}